ably\nbt-sensors-plugin-sk.","tree":{"sha":"833500feba0292304478dd0e35066824d42d3102","url":"https://api.github.com/repos/SignalK/signalk-server/git/trees/833500feba0292304478dd0e35066824d42d3102"},"url":"https://api.github.com/repos/SignalK/signalk-server/git/commits/7da0743a5134ed9ea4e88cacfdef6137649f1943","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/1049678?v=4","events_url":"https://api.github.com/users/tkurki/events{/privacy}","followers_url":"https://api.github.com/users/tkurki/followers","following_url":"https://api.github.com/users/tkurki/following{/other_user}","gists_url":"https://api.github.com/users/tkurki/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/tkurki","id":1049678,"login":"tkurki","node_id":"MDQ6VXNlcjEwNDk2Nzg=","organizations_url":"https://api.github.com/users/tkurki/orgs","received_events_url":"https://api.github.com/users/tkurki/received_events","repos_url":"https://api.github.com/users/tkurki/repos","site_admin":false,"starred_url":"https://api.github.com/users/tkurki/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/tkurki/subscriptions","type":"User","url":"https://api.github.com/users/tkurki","user_view_type":"public"},"html_url":"https://github.com/SignalK/signalk-server/commit/7da0743a5134ed9ea4e88cacfdef6137649f1943","node_id":"C_kwDOAUuXCdoAKDdkYTA3NDNhNTEzNGVkOWVhNGU4OGNhY2ZkZWY2MTM3NjQ5ZjE5NDM","parents":[{"html_url":"https://github.com/SignalK/signalk-server/commit/da8c04b01ba7f8b0d52c92aca5d73b6b163e20c2","sha":"da8c04b01ba7f8b0d52c92aca5d73b6b163e20c2","url":"https://api.github.com/repos/SignalK/signalk-server/commits/da8c04b01ba7f8b0d52c92aca5d73b6b163e20c2"}],"sha":"7da0743a5134ed9ea4e88cacfdef6137649f1943","url":"https://api.github.com/repos/SignalK/signalk-server/commits/7da0743a5134ed9ea4e88cacfdef6137649f1943"},{"author":{"avatar_url":"https://avatars.git