).","tree":{"sha":"1a32e335f974e6ca0a8f303832e6fb4136925be2","url":"https://api.github.com/repos/Jahia/addStuff/git/trees/1a32e335f974e6ca0a8f303832e6fb4136925be2"},"url":"https://api.github.com/repos/Jahia/addStuff/git/commits/71df3de81b17bab031db8100cdbd707f5b0d4c34","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/717177?v=4","events_url":"https://api.github.com/users/pvollenweider/events{/privacy}","followers_url":"https://api.github.com/users/pvollenweider/followers","following_url":"https://api.github.com/users/pvollenweider/following{/other_user}","gists_url":"https://api.github.com/users/pvollenweider/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/pvollenweider","id":717177,"login":"pvollenweider","node_id":"MDQ6VXNlcjcxNzE3Nw==","organizations_url":"https://api.github.com/users/pvollenweider/orgs","received_events_url":"https://api.github.com/users/pvollenweider/received_events","repos_url":"https://api.github.com/users/pvollenweider/repos","site_admin":false,"starred_url":"https://api.github.com/users/pvollenweider/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/pvollenweider/subscriptions","type":"User","url":"https://api.github.com/users/pvollenweider","user_view_type":"public"},"html_url":"https://github.com/Jahia/addStuff/commit/71df3de81b17bab031db8100cdbd707f5b0d4c34","node_id":"C_kwDOAV4vYdoAKDcxZGYzZGU4MWIxN2JhYjAzMWRiODEwMGNkYmQ3MDdmNWIwZDRjMzQ","parents":[{"html_url":"https://github.com/Jahia/addStuff/commit/304f898756b648787e7b401344731cbdc1140679","sha":"304f898756b648787e7b401344731cbdc1140679","url":"https://api.github.com/repos/Jahia/addStuff/commits/304f898756b648787e7b401344731cbdc1140679"}],"sha":"71df3de81b17bab031db8100cdbd707f5b0d4c34","url":"https://api.github.com/repos/Jahia/addStuff/commits/71df3de81b17bab031db8100cdbd707f5b0d4c34"},{"author":{"avatar_url":"https://av